+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void backendFetchesBoundedPagesUntilEveryVetIsLoaded() {
+        // Equal names exercise the ID tie-breaker across page boundaries.
+        dsl.batch(IntStream.range(0, 125)
+                .mapToObj(index -> dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                        .values("Alex", "Williams"))
+                .toList()).execute();
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertFalse(grid.isAllRowsVisible());
+        assertEquals(131, grid.getDataProvider().size(new Query<>()));
+
+        List<Vet> loaded = new ArrayList<>();
+        for (int offset = 0; offset < 131; offset += 40) {
+            List<Vet> page = grid.getDataProvider().fetch(new Query<>(offset, 40, List.of(), null, null)).toList();
+            assertEquals(Math.min(40, 131 - offset), page.size());
+            loaded.addAll(page);
+        }
+        assertEquals(131, loaded.stream().map(Vet::id).distinct().count());
+        assertEquals(loaded.subList(6, 131).stream().map(Vet::id).sorted().toList(),
+                loaded.subList(6, 131).stream().map(Vet::id).toList());
+        assertTrue(grid.getDataProvider().fetch(new Query<>(131, 40, List.of(), null, null)).findAny().isEmpty());
+    }
